From 23beacc7fecb56a05c734560c0bbd7fc24e458b7 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 12:10:20 +0100
Subject: [PATCH] startkde: source env scripts with the systemd user
 environment

Variables from environment.d were not passed to the plasma-workspace env
scripts, so a script appending to one replaced its value, and the sync
to systemd then dropped the environment.d part. Fill them in first.

BUG: 491579
---
 startkde/startplasma.cpp | 11 +++++++++++
 1 file changed, 11 insertions(+)

diff --git a/startkde/startplasma.cpp b/startkde/startplasma.cpp
index 9cda0be1e5..742eca59a9 100644
--- a/startkde/startplasma.cpp
+++ b/startkde/startplasma.cpp
@@ -155,7 +155,18 @@ void sourceFiles(const QStringList &files)

     filteredFiles.prepend(QStringLiteral(CMAKE_INSTALL_FULL_LIBEXECDIR "/plasma-sourceenv.sh"));

+    QProcessEnvironment environment = QProcessEnvironment::systemEnvironment();
+    if (const auto systemdEnvironment = getSystemdEnvironment()) {
+        const auto keys = systemdEnvironment->keys();
+        for (const QString &name : keys) {
+            if (!environment.contains(name) && !isShellVariable(QStringView(name)) && !isSessionVariable(name)) {
+                environment.insert(name, systemdEnvironment->value(name));
+            }
+        }
+    }
+
     QProcess p;
+    p.setProcessEnvironment(environment);
     p.start(QStringLiteral("/bin/sh"), filteredFiles);
     p.waitForFinished(-1);

